atNumber(asset.value)}</td>\n            <td class="percent-cell">${percent}%</td>\n            <td><span class="network-cell">${asset.network}</span></td>\n            <td>\n                <button class="delete-btn" onclick="deleteAsset(${asset.id})">??????????????</button>\n            </td>\n        `;\n        \n        tbody.appendChild(row);\n    });\n    \n    if (portfolio.assets.length === 0) {\n        tbody.innerHTML = `\n            <tr>\n                <td colspan="8" style="text-align: center; color: #64748b; padding: 40px;">\n                    ???????????????? ??????????????, ?????????? ?????????????? ????????????\n                </td>\n            </tr>\n        `;\n    }\n}\n\n// ???????????????????????????? ??????????\nfunction formatNumber(num) {\n    if (num === 0) return '0';\n    \n    if (num < 0.0001) {\n        return num.toExponential(4);\n    }\n    \n    if (num < 1) {\n        return num.toFixed(6);\n    }\n    \n    if (num < 1000) {\n        return num.toFixed(2);\n    }\n    \n    return num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n}\n\n// ???????????????????? ?? localStorage\nfunction savePortfolio() {\n    try {\n        localStorage.setItem('investPortfolio', JSON.stringify(portfolio));\n    } catch (e) {\n        console.error('???????????? ????????????????????:', e);\n    }\n}\n\n// ???????????????? ???? localStorage\nfunction loadPortfolio() {\n    try {\n        const saved = localStorage.getItem('investPortfolio');\n        if (saved) {\n            portfolio = JSON.parse(saved);\n        }\n    } catch (e) {\n        console.error('???????????? ????????????????:', e);\n    }\n}\n```\n\n---\n\n## ????????????! ?????? ???? ??????????????:\n\n??? **HTML** - ?????????????????? ?? ???????????? ???????????????????? ???????????????? ?? ???????????????? ????????????????  \n??? **CSS** - ?????????????????????? ???????????? ?? ??????????????????????????  \n??? **JavaScript** - ???????????? 